import * as T from './tycoon.js';
import * as E from './engine.js';
import {faceURL} from './faces.js';
import {CHARACTERS} from './story.js';
import {dialogueHtml} from './dialogue-presentation.js';
import {brandLogo} from './brands.js';
import {trainThumb} from './train3d.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>Number(x).toLocaleString('es-ES',{maximumFractionDigits:1});
const cash=x=>`${num(x)} M€`;
const portrait=(id,mood='happy')=>`<img class="tycoon-face" src="${faceURL(id,mood)}" alt="${esc(CHARACTERS[id]?.name)}" loading="lazy">`;
const button=(action,id,label,disabled=false,extra='',active=false)=>`<button class="btn small ${active?'active':''}" data-action="${action}" data-id="${esc(id)}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
const nav=(screen,label)=>`<button class="btn small" data-action="navigate" data-screen="${screen}">${label}</button>`;
const progress=(value,target,label)=>`<div class="goal-progress"><div class="split"><strong>${num(value)} / ${num(target)}</strong><span>${esc(label)}</span></div><progress max="${target}" value="${Math.min(target,Math.max(0,value))}" aria-label="${esc(label)}"></progress></div>`;
const details=(s,q,branch=q.branch)=>typeof T.contractDetails==='function'?T.contractDetails(s,q,branch,r=>E.metrics(s,r)):null;
export function directionCount(s){return s.tycoon.contracts.filter(q=>q.status==='offered'||q.status==='active'&&q.until-s.month<=3).length+(T.staffing(s)<1?1:0);}
function requirementLink(r){
 const action=['route','route-open','route-detail'].includes(r.action)?'route':r.action;
 return ['route','city','station-up','tycoon-tab'].includes(action)&&r.id?button(action,r.id,action==='route'?'Revisar servicio':action==='city'?'Ver estación':action==='station-up'?'Mejorar estación':'Ver opciones'):'';
}
function prerequisitesHTML(items=[]){
 if(!items.length)return '';
 const ready=items.every(p=>p.ready),reassignable=items.every(p=>p.ready||p.reassignable);
 return `<div class="material-readiness ${ready?'ready':'waiting'}"><strong>${ready?'Material disponible para este plan':reassignable?'Libera trenes antes de ampliar la oferta':'Revisa material operativo antes de firmar'}</strong>${ready?'':`<p>${reassignable?'Hay material compatible, pero necesitas reasignar unidades de otros servicios.':'La flota actual no cubre este plan. Comprueba el taller y las entregas frente al plazo del encargo.'}</p>`}<details><summary>Comprobar trenes y frecuencias</summary>${items.map(p=>{const lots=p.lots.filter(f=>f.compatible&&f.condition>=30).sort((a,b)=>Number(b.ready)-Number(a.ready)||b.available-a.available).slice(0,2);return `<div class="material-option"><b>${esc(p.name)}</b><small>${p.frequency} salidas por sentido${p.openCost?` · apertura ${cash(p.openCost)}`:''}</small>${lots.length?lots.map(f=>`<small>${esc(f.name)}: ${f.required} necesarios · ${f.available} libres</small>`).join(''):'<small>Sin lote compatible y operativo.</small>'}</div>`;}).join('')}${nav('fleet','Revisar parque y taller')}</details></div>`;
}
function requirementsHTML(items=[]){return `<ul class="contract-requirements">${items.map(r=>{
 const format=v=>r.unit==='percent'?`${num(v*100)} %`:r.unit==='euro'?`${num(v)} €`:r.unit==='points'?`${num(v)} %`:num(v);
 const values=r.kind==='active'?(r.done?'En servicio':'Pendiente de abrir'):Number.isFinite(r.current)&&Number.isFinite(r.target)?`Actual ${format(r.current)} · objetivo ${r.kind==='fare'?'≤':'≥'} ${format(r.target)}`:'';
 return `<li class="${r.done?'done':''}"><span class="requirement-check" aria-label="${r.done?'Cumplido':'Pendiente'}">${r.done?'✓':'○'}</span><div><strong>${esc(r.label)}</strong>${r.route?`<small class="requirement-route">${esc(r.route)}</small>`:''}<small>${values}${r.cost?` · inversión ${cash(r.cost)}`:''}</small>${r.note?`<small>${esc(r.note)}</small>`:''}</div>${!r.done?requirementLink(r):''}</li>`;
 }).join('')}</ul>`;}
function contractHTML(s,q){
 const [arcTitle,person,line]=T.ARCS[q.arc],d=details(s,q),remaining=Math.max(0,q.until-s.month);
 const status={offered:'Propuesta por decidir',active:'Compromiso en marcha',won:'Cumplido',lost:'Incumplido',declined:'Propuesta cerrada'}[q.status]||q.status;
 const labels={passengers:'viajes nuevos',stations:'niveles de estación nuevos',services:'servicios nuevos',research:'investigaciones terminadas',satisfaction:'de satisfacción',project:'meses de servicio estable'};
 const actionable=q.status==='offered'||q.status==='active';
 let body=`<article class="tycoon-contract story ${actionable?'live':'archived'} ${q.status==='active'&&remaining<=3?'urgent':''}">${portrait(person,q.status==='lost'?'angry':q.status==='won'?'proud':'worried')}<div class="contract-content"><div class="contract-meta"><span class="kicker">${esc(status)}${d?.stability?' · acuerdo operativo':d?.stage?` · etapa ${d.stage}/${d.stageTotal||3}`:''}</span>${actionable?`<span class="deadline ${remaining<=3?'neg':''}">${q.status==='offered'?'Decide en ':''}${remaining} meses · ${E.dateOf(q.until)}</span>`:''}</div><h2>${esc(d?.title||arcTitle)}</h2>${d?.routeName?`<p class="project-route"><b>Corredor:</b> ${esc(d.routeName)}</p>`:''}<p data-say="${esc(line)}">${dialogueHtml(line,person)}</p><button class="say-btn" data-action="say" data-person="${person}" data-where="${esc(`contract:${q.id}`)}" data-say-text aria-label="Escuchar diálogo" title="Escuchar diálogo" aria-pressed="false">Escuchar diálogo</button>`;
 if(q.status==='active'){
  body+=progress(Math.max(0,T.missionValue(s,q)),q.target,labels[q.goal]);
  if(q.goal==='project')body+='<p class="small muted">Necesitas tres cierres mensuales consecutivos con todos los requisitos. Si alguno deja de cumplirse, el contador vuelve a cero.</p>';
  if(d?.requirements){body+=requirementsHTML(d.requirements);if(d.requirements.length&&d.requirements.every(r=>r.done))body+=`<div class="contract-next"><strong>Servicio preparado.</strong><p>Mantén los requisitos durante ${Math.max(0,q.target-T.missionValue(s,q))} cierres mensuales más. Puedes jugar las jornadas o delegar el mes.</p>${button('skip-month','',s.ops?.phase==='running'?'Termina la jornada para delegar':'Delegar mes y comprobar progreso',s.ended||s.ops?.phase==='running')}</div>`;}
  else {
   const actions={passengers:nav('network','Ajustar oferta y tarifas'),services:nav('network','Abrir servicios'),stations:nav('network','Elegir una ciudad en el mapa'),research:button('tycoon-tab','research','Planificar investigación'),satisfaction:button('tycoon-tab','people','Revisar plantilla y políticas')};
   const tips={passengers:'Se cuentan los viajeros desde que firmaste este encargo. Revisa ocupación y margen antes de añadir trenes.',services:'Cada relación nueva debe tener material compatible y maquinistas para sostener sus salidas.',stations:'Pulsa una ciudad en el mapa y mejora su estación; cada nivel nuevo cuenta.',research:'Las investigaciones cuentan al terminar; reserva caja y comprueba su fecha de entrega.',satisfaction:'La fiabilidad, la plantilla y el mantenimiento influyen en la satisfacción al cerrar cada mes.'};
   body+=`<div class="contract-next"><p>${tips[q.goal]||'Mantén los requisitos durante los cierres mensuales.'}</p>${actions[q.goal]||nav('network','Revisar la red')}</div>`;
  }
 }
 if(q.status==='offered'){
  body+=`<p class="offer-explainer">Elige un compromiso. El premio se cobra al cumplirlo; no es un coste de firma.</p><div class="contract-branches">${['public','commercial'].map(branch=>{
   const b=details(s,q,branch),reward=b?.reward||(branch==='public'?q.reward:26),penalty=b?.penalty||(branch==='public'?q.penalty:8);
   return `<section><span class="kicker">${branch==='public'?'Servicio público':'Apuesta comercial'}</span><strong class="branch-reward">Premio ${cash(reward)}</strong><p>${branch==='public'?'Prioriza conexiones y mejora la confianza de Territorio.':'Mayor exigencia; mejora la confianza de Hacienda.'}</p>${prerequisitesHTML(b?.prerequisites)}${b?.requirements?requirementsHTML(b.requirements):`<p class="small">Objetivo: ${num(branch==='commercial'?Math.ceil(q.target*1.25):q.target)} ${labels[q.goal]}</p>`}${b?.bonus?.reward>0?`<details class="branch-bonus"><summary>Bonus opcional · +${cash(b.bonus.reward)}</summary>${requirementsHTML(b.bonus.requirements)}</details>`:''}<p class="small">${b?.months?`${b.months} meses desde la firma · `:''}Incumplir: −${cash(penalty)} y −8 Gobierno.</p>${button(branch==='public'?'tycoon-public':'tycoon-commercial',q.id,branch==='public'?'Aceptar servicio público':'Aceptar apuesta comercial',s.ended)}</section>`;
  }).join('')}</div><p class="small muted">Puedes dejar pasar la propuesta sin multa. El plazo termina en ${E.dateOf(q.until)}.</p>`;
 }else if(q.status==='active')body+=`<p class="contract-stakes">Al cumplir: <b>+${cash(q.reward)}</b> · incumplir: −${cash(q.penalty)} y −8 Gobierno.</p>`;
 if(d?.bonus?.reward>0&&q.status==='active')body+=`<details class="bonus-goal"><summary>Objetivo opcional · +${cash(d.bonus.reward)}</summary>${requirementsHTML(d.bonus.requirements)}</details>`;
 return body+'</div></article>';
}
function nextSteps(s){
 const t=s.tycoon,b=E.balance(s),cards=[];
 if(T.staffing(s)<1)cards.push(['Plantilla insuficiente',`${T.driverNeed(s)-t.drivers} maquinistas por debajo de lo necesario. La formación tarda tres meses.`,button('tycoon-tab','people','Preparar contrataciones'),'urgent']);
 if(b.net<0)cards.push(['Margen negativo',`Previsión ${cash(b.net)}/mes. Ajusta los servicios antes de financiar una expansión.`,nav('finance','Revisar las cuentas'),'urgent']);
 if(t.research)cards.push(['Investigación en curso',`${T.TECHS[t.research.id].name} · prevista para ${E.dateOf(t.research.due)}.`,button('tycoon-tab','research','Ver investigación'),'']);
 if(t.training.length)cards.push(['Personal en formación',`${t.training.reduce((n,x)=>n+x.count,0)} maquinistas; primer lote en ${E.dateOf(Math.min(...t.training.map(x=>x.due)))}.`,button('tycoon-tab','people','Ver plantilla'),'']);
 if(s.requests?.length){const q=s.requests[0];cards.push(['Una ciudad espera respuesta',`Peticiones abiertas: ${s.requests.length}. Revisa el objetivo y el plazo en la ficha de la ciudad.`,button('city',q.city,'Ver petición'),'']);}
 if(!cards.length)cards.push(['Hay margen para preparar el futuro','Compara demanda, material libre y plazos antes de ampliar la oferta.',nav('network','Buscar una oportunidad'),'']);
 return `<section class="direction-next"><h2 class="section">Próximos pasos</h2><div class="next-step-grid">${cards.slice(0,3).map(([title,text,action,cls])=>`<article class="${cls}"><h3>${title}</h3><p>${esc(text)}</p>${action}</article>`).join('')}</div></section>`;
}
export function tycoonPage(s,tab='agenda'){
 const t=s.tycoon,disabled=s.ended,balance=E.balance(s);
 let body=`<nav class="tycoon-tabs" aria-label="Dirección">${[['agenda','Agenda'],['market','Competencia'],['people','Personal y políticas'],['research','Investigación'],['paper','La Gaceta']].map(([id,label])=>button('tycoon-tab',id,label,false,tab===id?'aria-current="page"':'',tab===id)).join('')}</nav>`;
 if(tab==='agenda'){
  const live=t.contracts.filter(q=>q.status==='active'||q.status==='offered').sort((a,b)=>(a.status==='active'?0:1)-(b.status==='active'?0:1)||a.until-b.until),past=t.contracts.filter(q=>!['active','offered'].includes(q.status));
  body+=`<div class="tycoon-banner"><span class="kicker">${t.mode==='free'?'Modo libre · sin objetivos obligatorios':'Consejo de dirección'}</span><h2>Un plan para el próximo mes.</h2><p>Decide qué compromisos asumes y prepara trenes, personal y caja para cumplirlos.</p><div class="direction-facts"><span><b>${live.filter(q=>q.status==='active').length}</b> encargos en marcha</span><span><b>${t.completed}</b> cumplidos</span><span><b>${cash(s.cash)}</b> disponibles</span></div></div>`;
  body+=`<section class="calendar-plan"><div><strong>Elige el ritmo de tu gestión</strong><p>Jornadas para atender incidencias. Meses para avanzar obras, formación y encargos: se liquidan las cuentas y se comprueban tus compromisos.</p><p class="calendar-forecast">Previsión de explotación: <b class="${balance.net>=0?'pos':'neg'}">${cash(balance.net)}/mes</b>.</p>${balance.net<0?`<p class="calendar-loss">La compañía pierde dinero aunque un encargo cumpla su margen.</p>${nav('finance','Revisar cuentas antes de avanzar')}`:''}</div>${button('skip-month','',s.ops?.phase==='running'?'Jornada en curso':'Delegar mes',disabled||s.ops?.phase==='running', `title="${disabled?'El mandato ha terminado.':s.ops?.phase==='running'?'Cierra la jornada antes de delegar el mes.':'Avanza el resto del mes con ingresos, gastos y consecuencias reales.'}"`)}</section>`;
  body+=live.length?live.map(q=>contractHTML(s,q)).join(''):`<div class="callout"><strong>Agenda sin compromisos pendientes.</strong><p>Los encargos llegan cada seis meses cuando se resuelve el anterior. Puedes dedicar este tiempo a preparar tu red.</p></div>`;
  body+=nextSteps(s)+`<h2 class="section">El equilibrio del consejo</h2><p class="small">Cada grupo tiene consecuencias distintas. Negociar cuesta 8 M€ y suma 12 puntos de confianza.</p><div class="pressure-grid">`;
  const risks={government:'Por debajo de 15 durante seis meses: cese en campaña.',treasury:'Por debajo de 25: recargo mensual de Hacienda.',staff:'Por debajo de 25: huelgas y menor fiabilidad.',riders:'La confianza aumenta la demanda de tus servicios.',territory:'Por debajo de 25: pueden retrasarse las obras.'};
  body+=Object.entries(T.GROUPS).map(([id,[label,person]])=>{const trust=t.groups[id],reason=disabled?'El mandato ha terminado.':trust>=95?'Este grupo ya está convencido.':s.cash<8?'Necesitas 8 M€ disponibles.':'';return `<article class="pressure-card ${trust<25?'at-risk':''}">${portrait(person,trust<30?'angry':trust<55?'worried':'happy')}<div><div class="split"><strong>${label}</strong><b>${num(trust)}/100</b></div><meter min="0" max="100" value="${trust}" aria-label="Confianza de ${label}"></meter><p class="small">${risks[id]}</p>${button('tycoon-lobby',id,'Negociar · 8 M€',!!reason,reason?`title="${esc(reason)}"`:'')}${reason?`<small class="action-reason">${reason}</small>`:''}</div></article>`;}).join('')+'</div><p class="small muted">Desde 80 puntos: apoyo económico del Gobierno, ahorro de Hacienda, puntualidad de la Plantilla y más demanda de Viajeros y Territorio.</p>';
  if(past.length)body+=`<details class="contract-history"><summary>Encargos cerrados · ${past.length} · ${t.failed} incumplidos</summary>${past.map(q=>contractHTML(s,q)).join('')}</details>`;
  if(t.resolved.length)body+=`<details class="contract-history"><summary>Historial del mandato · ${t.resolved.length} compromisos</summary><ul class="contract-ledger">${[...t.resolved].reverse().map(q=>{const r=s.routes.find(r=>r.id===q.route);return `<li><span class="${q.result==='won'?'pos':q.result==='lost'?'neg':''}">${q.result==='won'?'✓ Cumplido':q.result==='lost'?'Incumplido':'Propuesta cerrada'}</span><strong>${esc(r?E.routeName(r):T.ARCS[q.arc]?.[0]||'Encargo')}${q.stage?` · etapa ${q.stage}`:''}</strong><small>${Number.isInteger(q.month)?E.dateOf(q.month):''}${q.reward?` · +${cash(q.reward)}`:''}</small></li>`;}).join('')}</ul></details>`;
 }else if(tab==='people'){
  const need=T.driverNeed(s),short=Math.max(0,need-t.drivers);
  body+=`<h2>Personal para sostener tu oferta.</h2><dl class="figures"><div><dt>Maquinistas</dt><dd>${t.drivers}</dd></div><div><dt>Necesarios</dt><dd>${need}</dd></div><div><dt>En formación</dt><dd>${t.training.reduce((n,x)=>n+x.count,0)}</dd></div><div><dt>Servicios cubiertos</dt><dd class="${short?'neg':'pos'}">${num(T.staffing(s)*100)} %</dd></div></dl>${short?`<p class="callout red"><strong>Faltan ${short} maquinistas.</strong> Se cancelan salidas hasta que termine la formación o reduzcas frecuencias.</p>`:'<p class="callout">Tu oferta actual dispone de suficiente plantilla. Prepara nuevas incorporaciones antes de ampliar frecuencias.</p>'}<div class="training-plan"><h3>Contratar 20 maquinistas</h3><p>0,3 M€ ahora · disponibles en ${E.dateOf(s.month+3)} · tres meses de formación.</p><p class="small">Cada maquinista sobre la plantilla inicial añade 1.500 €/mes de gasto.</p>${button('tycoon-hire','20','Contratar y formar 20 · 0,3 M€',disabled||s.cash<.3)}${s.cash<.3?'<small class="action-reason">Necesitas 0,3 M€ de caja.</small>':''}</div>${t.training.length?`<h3 class="section">Incorporaciones previstas</h3><div class="training-queue">${t.training.map(x=>`<div><strong>${x.count} maquinistas</strong><span>${E.dateOf(x.due)} · ${Math.max(0,x.due-s.month)} meses</span></div>`).join('')}</div>`:''}<h2 class="section">Políticas de empresa</h2><p class="small">Coste total adicional de políticas y plantilla: <b>${cash(T.monthlyCost(s))}/mes</b>.</p><div class="policy-grid">`;
  body+=Object.entries(T.POLICIES).map(([id,p])=>`<article class="${t.policies.includes(id)?'is-active':''}"><span class="kicker">${t.policies.includes(id)?'Activa':'Disponible'}</span><h3>${p.name}</h3>${id==='lowcost'?`<figure class="avarato-policy-preview" aria-label="AVArato, tu marca de bajo coste" style="margin:0 0 12px;"><div style="width:132px;max-width:100%;margin-bottom:8px;">${brandLogo('AVArato')}</div>${trainThumb('106avlo')}<figcaption class="small" style="margin-top:6px;">Tu marca de bajo coste.</figcaption></figure>`:''}<p>${p.note}</p><strong>${cash(p.cost)}/mes</strong>${button('tycoon-policy',id,t.policies.includes(id)?'Desactivar política':'Activar política',disabled,`aria-pressed="${t.policies.includes(id)}"`)}</article>`).join('')+'</div>';
 }else if(tab==='research'){
  body+=`<h2>Invierte con tiempo.</h2><p>Una investigación a la vez. El coste se paga al financiarla y sus efectos permanecen.</p><div class="policy-grid research-grid">${Object.entries(T.TECHS).map(([id,p])=>{
   const done=t.tech.includes(id),running=t.research?.id===id,missing=p.requires.filter(k=>!t.tech.includes(k)),reason=disabled?'El mandato ha terminado.':done?'Ya está implantada.':missing.length?`Completa antes: ${missing.map(k=>T.TECHS[k].name).join(', ')}.`:t.research&&!running?'Otra investigación ocupa el equipo.':s.cash<p.cost?`Faltan ${cash(p.cost-s.cash)} de caja.`:'';
   return `<article class="${done?'is-active':running?'in-progress':''}"><span class="kicker">${done?'Implantada':running?'En curso':missing.length?'Requisitos pendientes':'Lista para financiar'}</span><h3>${p.name}</h3><p>${p.note}</p><p class="investment-cost"><strong>${cash(p.cost)}</strong> · ${p.months} meses</p><p class="small">${running?`Final previsto: ${E.dateOf(t.research.due)}`:`Si empiezas ahora: ${E.dateOf(s.month+p.months)}`}</p><p class="small">Requiere: ${p.requires.map(k=>T.TECHS[k].name).join(', ')||'sin requisitos'}</p>${running?progress(Math.max(0,p.months-(t.research.due-s.month)),p.months,`${Math.max(0,t.research.due-s.month)} meses restantes`):button('tycoon-research',id,done?'Completada':'Financiar investigación',!!reason,reason?`title="${esc(reason)}"`:'')}${reason?`<small class="action-reason">${reason}</small>`:''}</article>`;
  }).join('')}</div>`;
 }else if(tab==='market'){
  const routes=s.routes.filter(r=>r.active&&T.competition(s,r).length);
  body+=`<h2>Compite sin perder el margen.</h2><p>OuiOui compite por precio; YaIré, por calidad. Compara tarifa, frecuencia, ocupación y resultado antes de responder.</p>${!t.rivals?'<p class="callout">Competencia desactivada en este modo libre.</p>':!routes.length?'<p class="callout">Todavía no hay rivales en tus servicios activos. Llegarán a otros corredores con el paso de los años.</p>':''}`;
  body+=routes.map(r=>{const m=E.metrics(s,r);return `<article class="market-row"><h3>${esc(E.routeName(r))}</h3><dl class="market-figures"><div><dt>Tu tarifa</dt><dd>${num(r.fare)} €</dd></div><div><dt>Salidas / sentido</dt><dd>${r.frequency}</dd></div><div><dt>Ocupación</dt><dd>${num(m.occupancy*100)} %</dd></div><div><dt>Margen / mes</dt><dd class="${m.net>=0?'pos':'neg'}">${cash(m.net)}</dd></div></dl>${T.competition(s,r).map(c=>`<span class="competitor" style="border-color:${c.color}"><span style="display:block;width:88px;">${brandLogo(c.name)}</span><b>${esc(c.name)}</b><span>${num(c.fare)} € · ${c.frequency} trenes · calidad ${num(c.quality)}${c.war?' · GUERRA DE PRECIOS':''}</span>${c.strategy?`<small>${esc({hold:'Mantiene su oferta',price:'Baja precios',capacity:'Amplía frecuencias',quality:'Mejora calidad'}[c.strategy]||c.strategy)}${Number.isFinite(c.nextReview)?` · revisión en ${E.dateOf(c.nextReview)}`:''}</small>`:''}</span>`).join('')}<p class="small">Tu cuota estimada: ${num(m.share*100)} % · fiabilidad: ${num(m.punctuality)} %.</p>${button('route',r.id,'Revisar tarifa y frecuencias')}</article>`;}).join('');
 }else{
  body+=`<div class="gazette"><span>EDICIÓN MENSUAL · FUNDADO EN 2022</span><h2>La Gaceta del Andén</h2><p>Si llega tarde, es por causas ajenas.</p>${t.paper.length?t.paper.map(x=>`<article><small>${E.dateOf(x.month)}</small><h3>${esc(x.title)}</h3></article>`).join(''):'<p>La primera edición sale al cerrar el mes.</p>'}</div><h2 class="section">La vitrina de los méritos</h2>${t.achievements.length?`<ul class="achievement-list">${t.achievements.map(a=>`<li>★ ${esc(a)}</li>`).join('')}</ul>`:'<p>Cumple encargos, investiga y conecta ciudades para ganar logros.</p>'}`;
 }
 return body;
}
